void handler(int sig) {
    if (sig == SIGUSR1) {
        // Signal received from kernel/another process
        printf("Received signal %d\n", sig);
    }
}

// Set up ECF handler via sigaction
struct sigaction sa;
sa.sa_handler = handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = SA_RESTART;
sigaction(SIGUSR1, &sa, NULL);

// Send signal to self (ECF event triggered)
if (fork() == 0) {
    kill(getppid(), SIGUSR1);
    _exit(0);
}
